package io.github.ryanoviski.hestia.presentation.controllers;

import io.github.ryanoviski.hestia.application.dto.*;import io.github.ryanoviski.hestia.config.ApplicationContext;import io.github.ryanoviski.hestia.domain.enums.*;import io.github.ryanoviski.hestia.domain.models.*;import javafx.application.Platform;import javafx.embed.swing.SwingFXUtils;import javafx.fxml.FXML;import javafx.geometry.*;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.scene.image.*;import javafx.scene.layout.*;import javafx.stage.*;import javafx.util.StringConverter;import java.io.File;import java.nio.file.*;import java.time.format.DateTimeFormatter;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;

public final class DocumentsController {
 @FXML private TextField nameFilter;@FXML private ComboBox<Profile>profileFilter;@FXML private ComboBox<DocumentType>typeFilter;@FXML private ComboBox<TransactionType>transactionTypeFilter;@FXML private ComboBox<String>originFilter;@FXML private ComboBox<AttachmentIntegrity>integrityFilter;@FXML private DatePicker fromFilter,toFilter;@FXML private VBox documentsList;@FXML private Label emptyState;private ApplicationContext context;private final AtomicLong renderToken=new AtomicLong();private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy");
 public void configure(ApplicationContext c){context=c;profileFilter.getItems().setAll(c.profileService().listProfiles());typeFilter.getItems().setAll(DocumentType.values());typeFilter.setConverter(converter(DocumentType::displayName));transactionTypeFilter.getItems().setAll(TransactionType.values());integrityFilter.getItems().setAll(AttachmentIntegrity.values());integrityFilter.setConverter(converter(AttachmentIntegrity::displayName));originFilter.getItems().setAll("Movimentação","Perfil");refresh();}
 @FXML private void refresh(){var filter=new AttachmentFilter(nameFilter.getText(),id(profileFilter.getValue()),typeFilter.getValue(),transactionTypeFilter.getValue(),fromFilter.getValue(),toFilter.getValue(),originFilter.getValue()==null?null:originFilter.getValue().equals("Movimentação"),integrityFilter.getValue());var items=context.attachmentService().search(filter);documentsList.getChildren().clear();items.forEach(a->documentsList.getChildren().add(row(a)));emptyState.setVisible(items.isEmpty());emptyState.setManaged(items.isEmpty());if(items.isEmpty())documentsList.getChildren().add(emptyState);}
 @FXML private void addProfileDocument(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Adicionar documento ao perfil");ComboBox<Profile>profile=new ComboBox<>();profile.getItems().setAll(context.profileService().listProfiles());ComboBox<DocumentType>type=new ComboBox<>();type.getItems().setAll(DocumentType.values());type.setConverter(converter(DocumentType::displayName));type.setValue(DocumentType.OTHER);TextField description=new TextField();GridPane g=new GridPane();g.setHgap(8);g.setVgap(8);g.addRow(0,new Label("Perfil"),profile);g.addRow(1,new Label("Tipo"),type);g.addRow(2,new Label("Descrição"),description);d.getDialogPane().setContent(g);d.getDialogPane().getButtonTypes().addAll(ButtonType.NEXT,ButtonType.CANCEL);if(d.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.NEXT||profile.getValue()==null)return;File file=chooser("Selecionar documento").showOpenDialog(documentsList.getScene().getWindow());if(file!=null){try{context.attachmentService().importForProfile(profile.getValue().id(),type.getValue(),description.getText(),file.toPath());refresh();}catch(RuntimeException e){error(e.getMessage());}}}
 @FXML private void diagnose(){StorageDiagnostic d=context.attachmentService().diagnose();new Alert(Alert.AlertType.INFORMATION,"Registros sem arquivo: "+d.missingRecords().size()+"\nArquivos sem registro: "+d.orphanFiles().size()+"\nTemporários abandonados: "+d.temporaryFiles().size(),ButtonType.OK).showAndWait();}
 private HBox row(Attachment a){VBox info=new VBox(3,new Label(a.originalFilename()),new Label(a.documentType().displayName()+" · "+formatSize(a.sizeBytes())+" · "+a.fileExtension().toUpperCase()+" · "+DATE.format(a.createdAt().atZone(java.time.ZoneId.systemDefault()).toLocalDate())),new Label((a.profileName()==null?"":a.profileName())+(a.transactionDescription()==null?"":" · "+a.transactionDescription())));info.getChildren().get(0).getStyleClass().add("transaction-description");info.getChildren().get(1).getStyleClass().add("profile-meta");Label integrity=new Label(a.integrity().displayName());integrity.getStyleClass().addAll("status-pill",a.integrity()==AttachmentIntegrity.AVAILABLE?"status-settled":"status-overdue");Region spacer=new Region();HBox.setHgrow(spacer,Priority.ALWAYS);HBox row=new HBox(8,info,spacer,integrity,button("Visualizar",()->preview(a)),button("Abrir",()->context.attachmentService().openExternal(a.id()).exceptionally(e->{Platform.runLater(()->error(e.getCause()==null?e.getMessage():e.getCause().getMessage()));return null;})),button("Exportar",()->export(a)),button("Verificar",()->{context.attachmentService().verify(a.id());refresh();}),button("Remover",()->remove(a)));row.setAlignment(Pos.CENTER_LEFT);row.getStyleClass().add("transaction-row");return row;}
 private void preview(Attachment a){if(a.integrity()!=AttachmentIntegrity.AVAILABLE){error("O arquivo está ausente, alterado ou inválido.");return;}Stage stage=new Stage();ImageView view=new ImageView();view.setPreserveRatio(true);view.setFitWidth(850);view.setFitHeight(620);Label status=new Label("Carregando...");Button previous=new Button("Anterior"),next=new Button("Próxima"),minus=new Button("−"),plus=new Button("+");HBox controls=new HBox(8,previous,next,minus,plus,status);controls.setAlignment(Pos.CENTER);BorderPane pane=new BorderPane(new ScrollPane(view),controls,null,null,null);stage.setScene(new Scene(pane,900,700));stage.setTitle(a.originalFilename());stage.show();final int[]page={0},pages={1};final float[]dpi={110};Runnable render=()->{long token=renderToken.incrementAndGet();status.setText("Carregando...");CompletableFuture.supplyAsync(()->a.mediaType().equals("application/pdf")?context.documentPreviewService().renderPdf(context.attachmentService().file(a),page[0],dpi[0]):context.documentPreviewService().loadImage(context.attachmentService().file(a),1600,1200)).thenAccept(image->Platform.runLater(()->{if(token==renderToken.get()){view.setImage(SwingFXUtils.toFXImage(image,null));status.setText(a.mediaType().equals("application/pdf")?"Página "+(page[0]+1)+" de "+pages[0]:formatSize(a.sizeBytes()));}})).exceptionally(e->{Platform.runLater(()->status.setText("Não foi possível visualizar."));return null;});};if(a.mediaType().equals("application/pdf"))pages[0]=context.documentPreviewService().pdfPageCount(context.attachmentService().file(a));else{previous.setDisable(true);next.setDisable(true);}previous.setOnAction(e->{if(page[0]>0){page[0]--;render.run();}});next.setOnAction(e->{if(page[0]+1<pages[0]){page[0]++;render.run();}});minus.setOnAction(e->{dpi[0]=Math.max(55,dpi[0]-20);render.run();});plus.setOnAction(e->{dpi[0]=Math.min(220,dpi[0]+20);render.run();});render.run();}
 private void export(Attachment a){FileChooser c=new FileChooser();c.setInitialFileName(a.originalFilename());File f=c.showSaveDialog(documentsList.getScene().getWindow());if(f==null)return;boolean overwrite=!f.exists()||new Alert(Alert.AlertType.CONFIRMATION,"Substituir o arquivo existente?",ButtonType.CANCEL,ButtonType.OK).showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK;if(overwrite)try{context.attachmentService().export(a.id(),f.toPath(),true);}catch(RuntimeException e){error(e.getMessage());}}
 private void remove(Attachment a){if(new Alert(Alert.AlertType.CONFIRMATION,"O arquivo local será removido. A movimentação ou perfil será preservado.",ButtonType.CANCEL,ButtonType.OK).showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK){try{context.attachmentService().remove(a.id());refresh();}catch(RuntimeException e){error(e.getMessage());}}}
 private FileChooser chooser(String title){FileChooser c=new FileChooser();c.setTitle(title);c.getExtensionFilters().add(new FileChooser.ExtensionFilter("PDF e imagens","*.pdf","*.png","*.jpg","*.jpeg"));return c;}private Button button(String text,Runnable action){Button b=new Button(text);b.getStyleClass().add("table-action");b.setOnAction(e->action.run());return b;}private Long id(Profile p){return p==null?null:p.id();}private String formatSize(long size){return size<1024?size+" B":size<1024*1024?String.format("%.1f KB",size/1024d):String.format("%.1f MB",size/1024d/1024d);}private void error(String text){new Alert(Alert.AlertType.ERROR,text==null?"Não foi possível concluir a operação.":text,ButtonType.OK).showAndWait();}private <T>StringConverter<T>converter(java.util.function.Function<T,String>label){return new StringConverter<>(){public String toString(T value){return value==null?"":label.apply(value);}public T fromString(String s){return null;}};}
}
